// Scaleform GFx 3.3.89 - GENERATED layout assertions, do not edit by hand.
// One sizeof check per reconstructed type and one offsetof check per member, against the 2012
// Shipping PDB. This is the translation unit of the gfx3 library: if it compiles, the
// reconstruction agrees with the PDB byte for byte.
#include "GFx3.h"

#define GFX3_ASSERT_SIZE(T, N) \
    static_assert(sizeof(T) == (N), "GFx3 layout: sizeof(" #T ") != " #N)
#define GFX3_ASSERT_OFFSET(T, M, N) \
    static_assert(offsetof(T, M) == (N), "GFx3 layout: offsetof(" #T ", " #M ") != " #N)

